def ensure_live_connection():
    """One cheap ping per rerun: a silently dropped cloud connection is replaced at once
    instead of hanging for minutes on a dead socket."""
    last = st.session_state.get("_last_ping")
    if last and (datetime.now() - last).total_seconds() < 20:   # alive a moment ago: skip the extra round trip
        return
    try:
        conn = get_conn()
        with conn.cursor() as cur:
            cur.execute("SELECT 1")
        conn.rollback()
        st.session_state["_last_ping"] = datetime.now()
    except Exception:
        st.session_state.pop("_last_ping", None)
        try:
            _connect.clear()
        except Exception:
            pass


