    run("INSERT INTO users (username, password, role, full_name, status, created_at) VALUES (%s,%s,'Store Officer',%s,'Pending',%s)",
        (username, hash_password(pw), full_name, datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
