@tx
def save_transaction(fac, item, qty, ttype, tx_dt, notes, verified, xfer_ok, supplier="", challan="", po_pending=False,
                     erp_open=None, price_open=None, rate=None, rate_mode=None, req_no=""):
    user = st.session_state.get("user", "")
    req_no = (req_no or "").strip() if ttype in ISSUE_TYPES else ""
    sl, pid, name = item["sl_no"], item["prod_id"], item["item_name"]
    stock = float(item["stock"] or 0)
    date_s, time_s, day = tx_dt.strftime(DATE_FMT), datetime.now().strftime("%I:%M %p"), tx_dt.day
    verif = "Verified"
    po_flag, po_date = ("Pending", date_s) if po_pending else ("", None)   # "ERP PO Pending" box ticked at entry

    if ttype == OPENING_TYPE:
        # Sets physical (qty) and ERP stock together and always leaves a transaction row with old -> new values.
        old_phys, old_erp = stock, float(item.get("erp") or 0)
        new_erp = float(erp_open or 0)
        old_price = float(item.get("price") or 0)
        new_price = float(price_open) if price_open else old_price
        if new_price > 0:
            run("UPDATE inventory SET unit_price=%s WHERE sl_no=%s AND factory_name=%s", (new_price, sl, fac))
        run("UPDATE inventory SET current_stock=%s, erp_stock=%s WHERE sl_no=%s AND factory_name=%s",
            (float(qty), new_erp, sl, fac))
        insert_tx(fac, user, sl, pid, name, qty, ttype, day,
                  f"{notes} | Opening set: Physical {old_phys:g}->{qty:g}, ERP {old_erp:g}->{new_erp:g}, "
                  f"Price {old_price:g}->{new_price:g}".strip(" |"),
                  date_s, time_s, "Verified")
        audit("OPENING_BALANCE", f"{fac}: {pid} ({name}) Physical {old_phys:g}->{qty:g}, ERP {old_erp:g}->{new_erp:g}")
        return True

    if ttype in ISSUE_TYPES:
        needed, _streak = verification_needed(fac, sl, tx_dt)
        if needed and not verified:
            st.error("Physical verification required: 3 calendar days have passed since the first unverified issue (gaps count). Verify before saving.")
            return False
        verif = "Physically Verified" if (needed and verified) else "Not Required"

    if ttype in ISSUE_TYPES and qty > stock:
        shortage = qty - stock
        other = find_same_in_other(pid, name, other_factory(fac), item["size"], need=shortage)
        if not other or float(other["stock"] or 0) < shortage or not xfer_ok:
            st.error("Transfer possible nay / confirm kora hoy nai.")
            return False
        ref_no = f"TRF-{datetime.now():%Y%m%d%H%M%S%f}"
        run("UPDATE inventory SET current_stock=current_stock-%s WHERE sl_no=%s AND factory_name=%s",
            (shortage, other["sl_no"], other["factory_name"]))
        run("UPDATE inventory SET current_stock=current_stock+%s WHERE sl_no=%s AND factory_name=%s", (shortage, sl, fac))
        run("""INSERT INTO inter_factory_transfers (transfer_ref, source_factory, dest_factory, prod_id, item_name, qty,
               transfer_date, transfer_time, initiated_by, status, notes, size) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,'Completed',%s,%s)""",
            (ref_no, other["factory_name"], fac, pid, name, shortage, date_s, time_s, user,
             f"Auto-transfer for shortage during issue (source item: {other['item_name']} [{other['prod_id']}]) | Size: {item['size'] or '-'}",
             item["size"] or ""))
        run("UPDATE inventory SET current_stock=current_stock-%s WHERE sl_no=%s AND factory_name=%s", (qty, sl, fac))
        insert_tx(fac, user, sl, pid, name, qty, ttype, day,
                  f"{notes} [Auto-transferred {shortage:g} pcs (size {item['size'] or '-'}) from {other['factory_name']}]".strip(),
                  date_s, time_s, verif, po_flag=po_flag, po_date=po_date, req_no=req_no)
        audit("AUTO_TRANSFER", f"{shortage:g} pcs from {other['factory_name']} to {fac} for {pid} (size {item['size'] or '-'})")
        return True

    if ttype in RECEIPT_TYPES:
        grn = "Pending" if ttype == "Supplier. Rec" else "Not Required"
        run("UPDATE inventory SET current_stock=current_stock+%s WHERE sl_no=%s AND factory_name=%s", (qty, sl, fac))
        tx_price = float(item.get("price") or 0)
        price_note = ""
        if ttype == "Supplier. Rec" and rate and float(rate) > 0:
            # Purchase rate typed on the receipt: it becomes the item's Unit Price, so Issues of this item reach the budget.
            rate, old_p = float(rate), tx_price
            if rate_mode == "Weighted average" and old_p > 0 and stock > 0:
                new_p = round((stock * old_p + qty * rate) / (stock + qty), 4)
            elif rate_mode == "Keep current price" and old_p > 0:
                new_p = None
            else:
                new_p = rate
            if new_p is not None and abs(new_p - old_p) > 1e-9:
                run("UPDATE inventory SET unit_price=%s WHERE sl_no=%s AND factory_name=%s", (new_p, sl, fac))
            tx_price = rate
            price_note = f" [Purchase rate {rate:g}; unit price {old_p:g}->{(old_p if new_p is None else new_p):g}]"
        insert_tx(fac, user, sl, pid, name, qty, ttype, day, notes, date_s, time_s, "Verified", grn,
                  supplier if ttype == "Supplier. Rec" else "", challan if ttype == "Supplier. Rec" else "",
                  po_flag=po_flag, po_date=po_date,
                  unit_price_at_tx=tx_price if ttype == "Supplier. Rec" else None)
        if price_note:
            audit("PURCHASE_RATE", f"{fac}: {pid} ({name}){price_note}")
    else:
        if qty > stock:
            st.error(f"Available stock ({stock:g}) kom ache requested qty ({qty:g}) theke.")
            return False
        run("UPDATE inventory SET current_stock=current_stock-%s WHERE sl_no=%s AND factory_name=%s", (qty, sl, fac))
        insert_tx(fac, user, sl, pid, name, qty, ttype, day, notes, date_s, time_s, verif,
                  po_flag=po_flag, po_date=po_date, req_no=req_no)
    audit("TRANSACTION", f"{fac}: {ttype} {qty:g} of {pid} ({name})" + (f" [SR {req_no}]" if req_no else "")
          + (" [ERP PO Pending ticked]" if po_pending else ""))
    return True


@tx
def delete_transaction(tid):
    t = q("SELECT * FROM transactions WHERE id=%s", (tid,))[0]
    if t["trans_type"] in RECEIPT_TYPES:
        run("UPDATE inventory SET current_stock=current_stock-%s WHERE sl_no=%s AND factory_name=%s", (t["qty"], t["sl_no"], t["factory_name"]))
    elif t["trans_type"] in ISSUE_TYPES + (ADJ_OUT,):
        run("UPDATE inventory SET current_stock=current_stock+%s WHERE sl_no=%s AND factory_name=%s", (t["qty"], t["sl_no"], t["factory_name"]))
    run("DELETE FROM transactions WHERE id=%s", (tid,))
    audit("DELETE_TRANS", f"Deleted transaction ID {tid}: {t['factory_name']} {t['trans_type']} {float(t['qty'] or 0):g} of "
                          f"{t['prod_id']} ({t['item_name']}) SL {t['sl_no']} by {t['officer_name']} on {t['date']} {t['time']}, stock reverted")
    return True


@tx
def update_tx_meta(tid, date_s, notes):
    old = q("SELECT factory_name, trans_type, qty, prod_id, item_name, sl_no, date, notes FROM transactions WHERE id=%s", (tid,))
    run("UPDATE transactions SET date=%s, notes=%s WHERE id=%s", (date_s, notes, tid))
    if old:
        o = old[0]
        audit("EDIT_TRANS", f"Transaction {tid}: {o['factory_name']} {o['trans_type']} {float(o['qty'] or 0):g} of {o['prod_id']} "
                            f"({o['item_name']}) SL {o['sl_no']}: date '{o['date']}' -> '{date_s}', notes '{o['notes'] or ''}' -> '{notes or ''}'")
    else:
        audit("EDIT_TRANS", f"Transaction {tid}: date/notes edited")
    return True


def zebra_styles(row):
    # row stripes + alternating column bands (st.dataframe cannot draw cell borders, so columns are separated by tint)
    shades = (("#FFFFFF", "#F1F7FF"), ("#EAF3FF", "#DCEBFF"))[row.name % 2]
    return [f"background-color:{shades[j % 2]}" for j in range(len(row))]


def tx_manager_panel(df, kp, title="🔐 Manager: Delete / Edit a transaction"):
    """Edit (date / remarks) or delete (stock is reverted) one of the transactions shown in the table above.
    Needs the Store Manager password; deletion also needs an explicit confirmation tick."""
    with st.expander(title):
        if df is None or df.empty:
            st.caption("Kono transaction nei.")
            return
        rows = {int(r["id"]): r for r in df.head(500).to_dict("records")}
        tid = int(st.selectbox("Transaction ID", list(rows), key=f"{kp}_mgr_id",
                               format_func=lambda i: f"ID {i} | {rows[i].get('item_name', '')} | qty {rows[i].get('qty', '')} | {rows[i].get('date', '')}"))
        cur = q_c("SELECT date, notes FROM transactions WHERE id=%s", (tid,))
        if not cur:
            st.warning("Transaction paoa jay nai (ager-i delete hoye thakte pare).")
            return
        pw_ok = mgr_check(f"{kp}_mgr_pw")
        conf = confirm_box(f"{kp}_del_conf_{tid}", "⚠️ Ami confirm korchi - transaction delete hobe ar stock revert hobe.")
        if st.button("🗑 Delete & revert stock", key=f"{kp}_del"):
            if not pw_ok:
                st.error("Manager password thik nei.")
            elif not conf:
                st.error("Delete confirm tick korun.")
            elif delete_transaction(tid):
                done("Transaction deleted, stock reverted.")
        cur_d = parse_date(cur[0]["date"])
        ed = st.date_input("New date", value=cur_d.date() if cur_d else date.today(), key=f"{kp}_ed_date_{tid}")
        en = st.text_input("Remarks", value=cur[0]["notes"] or "", key=f"{kp}_ed_notes_{tid}")
        if st.button("💾 Save edit", key=f"{kp}_ed_btn"):
            if not pw_ok:
                st.error("Manager password thik nei.")
            elif update_tx_meta(tid, ed.strftime(DATE_FMT), en.strip()):
                done("Transaction updated.")


def tab_transactions():
    fac, fsql, fp = FAC, FSQL, FP
    today_s = local_now().strftime(DATE_FMT)
    _cnt = q_c(f"""SELECT COUNT(*) AS n, COALESCE(SUM(CASE WHEN COALESCE(current_stock,0) <= 5 THEN 1 ELSE 0 END),0) AS low
                 FROM inventory WHERE 1=1{fsql}""", fp)[0]   # one query instead of two
    total_items = int(_cnt["n"] or 0)
    low_stock_items = int(_cnt["low"] or 0)
    today_transactions = int(q_c(f"SELECT COUNT(*) AS n FROM transactions WHERE date=%s{fsql}", [today_s] + fp)[0]["n"] or 0)

    st.title("Transactions")
    st.caption("Record stock movements and review recent activity.")
    k1, k2, k3 = st.columns(3)
    k1.metric("Inventory items", f"{total_items:,}")
    k2.metric("Low stock items", f"{low_stock_items:,}")
    k3.metric("Today's transactions", f"{today_transactions:,}")
    g = st.session_state.get("tx_gen", 0)   # bumps after every successful save -> all entry widgets start fresh
    if total_items == 0 and not is_cons_view:
        st.info("📦 Ei factory-r inventory khali. [2] INVENTORY → ➕ Add / Import theke opening stock upload korun.")
    left, right = st.columns([1.05, 2], gap="large")

    def _tx_quick_add_item(g):
        """Supplier Receipt only: item not in the list -> create it right here (same fields and rules as
        Inventory > Add New Item, opening stock 0 because the receipt itself adds the stock), then it is selected."""
        with st.expander("➕ Item তালিকায় নেই? এখান থেকে নতুন Item add করুন"):
            ensure_master_tables()
            k = f"txqa_{g}_"

            def _qa_dept_changed():   # Budget Category depends on Department
                st.session_state[k + "cat"] = SEL
            a1, a2, a3 = st.columns(3)
            qa_name = a1.text_input("Item Name*", key=k + "name")
            qa_code = a2.text_input("ERP Code (blank = temporary)", key=k + "code")
            qa_size = a3.text_input("Size (optional)", key=k + "size")
            try:
                similar_item_alert(FAC, qa_name, qa_size)   # soft warning only - never blocks saving
            except Exception:
                pass
            b1, b2, b3 = st.columns(3)
            qa_dept = b1.selectbox("Department*", list(DEPARTMENTS), key=k + "dept", on_change=_qa_dept_changed)
            qa_cat = b2.selectbox("Budget Category*", [SEL] + get_budget_categories(FAC, qa_dept), key=k + "cat")
            qa_pcat = b3.selectbox("Product Category*", [SEL] + get_product_categories(), key=k + "pcat")
            c1, c2 = st.columns(2)
            qa_uom = c1.selectbox("UOM*", [SEL] + get_uoms(), key=k + "uom")
            qa_price = c2.number_input("Unit Price (BDT) — optional", min_value=0.0, step=1.0, key=k + "price",
                                       help="Khali rakhle pore niche 'Purchase Rate' dilei Unit Price boshe jabe.")
            st.caption("Opening stock 0 thakbe; ei receipt-er Quantity diye stock barbe. Save korar por item-ti nijei select hoye jabe.")
            if st.button("💾 Item Save kore Select korun", key=k + "save", use_container_width=True) and guard():
                missing = [lbl for lbl, bad in (("Item Name", not qa_name.strip()), ("Budget Category", qa_cat == SEL),
                                                 ("Product Category", qa_pcat == SEL), ("UOM", qa_uom == SEL)) if bad]
                if missing:
                    st.error("Required: " + ", ".join(missing) + ".")
                else:
                    res = add_item(FAC, qa_code, qa_name.strip(), qa_size.strip(), qa_dept, qa_cat, 0.0, qa_price,
                                   "", qa_uom, qa_pcat)
                    if res:
                        st.session_state["_tx_prefill_sl"] = res[1]
                        done(f"Item ager theke chilo - select kora holo: {qa_name.strip()}" if res[0] == "exists"
                             else f"New item added: {qa_name.strip()} [{qa_size.strip() or 'no size'}] · ERP Code {res[2]} "
                                  "- ekhon Quantity ar Purchase Rate diye receipt save korun.")

    @_frag   # typing / picking in the entry form re-runs ONLY this block (not the recent list, alerts, header ...)
    def _tx_entry_form():
        g = st.session_state.get("tx_gen", 0)
        _pf = st.session_state.pop("_tx_prefill_sl", None)   # item just created from the Supplier Receipt form -> pick it
        if _pf:
            st.session_state[f"tx_search_{g}"] = ""
            st.session_state[f"tx_key_{g}"] = str(_pf)
        try:
            form_box = st.container(border=True, key="tx_form_box")
        except TypeError:   # very old Streamlit without container(key=...)
            form_box = st.container(border=True)
        with form_box:
            st.markdown('<div class="section-title">New Transaction</div>', unsafe_allow_html=True)
            st.markdown(f'<span class="officer-pill">👤 Officer: {html_lib.escape(str(st.session_state.get("user", "-")))}</span>',
                        unsafe_allow_html=True)
            if is_cons_view:
                st.warning("CONSOLIDATED view-te entry hoy na. Sidebar theke factory select korun.")
            type_label = st.selectbox("Transaction Type", list(TRANS_CODES), key="tx_type")
            ttype = TRANS_CODES[type_label]
            supplier, challan = "", ""
            if ttype == "Supplier. Rec":
                supplier_col, challan_col = st.columns(2, gap="small")
                supplier = supplier_col.text_input(
                    "Supplier", key=f"tx_supplier_{g}", placeholder="Supplier name"
                )
                challan = challan_col.text_input(
                    "Challan No.", key=f"tx_challan_{g}", placeholder="Delivery note number"
                )
            # Items with stock 0 (or negative) can not be issued / reduced, so they are not offered for those types.
            # Receipts and (+) adjustments still see every item, otherwise an item at 0 could never be restocked.
            stock_only = ttype in ISSUE_TYPES or ttype == ADJ_OUT
            search_col, exact_col = st.columns([1.35, 1], gap="small")
            search = search_col.text_input(
                "🔎 Search item", key=f"tx_search_{g}",
                placeholder="Name, serial, size or ERP code"
            )
            key = exact_col.text_input(
                "SL / ERP / Serial", key=f"tx_key_{g}",
                placeholder="Exact code or SL number"
            )
            item, blocked, need_xfer, xfer_ok = None, False, False, False
            if search.strip():
                cands = search_items(fac, search.strip(), stock_only)
                if cands:
                    opts = {item_label(c): c for c in cands}
                    item = opts[st.selectbox("Choose matching item", list(opts), key=f"tx_pick_{g}")]
                elif stock_only and search_items(fac, search.strip(), False):
                    st.warning("Item found, but current stock is 0; it cannot be issued.")
                else:
                    st.warning("No matching item found.")
            elif key.strip():
                item, cands = resolve_item(fac, key.strip(), stock_only)
                if item is None:
                    if cands:
                        st.error(f"{len(cands)} items match; enter an exact SL or serial number.")
                    else:
                        alt = resolve_item(fac, key.strip(), False)[0] if stock_only else None
                        if alt is not None:
                            st.warning(f"{alt['item_name']} was found, but its stock is {float(alt['stock']):g}; issue is blocked.")
                        else:
                            st.error("No item found for that SL / ERP / serial value.")

            if ttype == "Supplier. Rec":
                _tx_quick_add_item(g)

            qc, dc = st.columns(2)
            qty = qc.number_input("Physical Stock" if ttype == OPENING_TYPE else "Quantity",
                                  min_value=0.0, step=1.0, key=f"tx_qty_{g}")
            erp_open, price_open = None, None
            if ttype == OPENING_TYPE:
                # Shown ONLY for Opening Balance - Issue / Receipt forms never see these boxes.
                sl_key = item["sl_no"] if item is not None else 0
                ob1, ob2 = st.columns(2, gap="small")
                erp_open = ob1.number_input("ERP Stock", min_value=0.0, step=1.0,
                                            value=float(item["erp"]) if item is not None else 0.0,
                                            key=f"tx_erp_open_{g}_{sl_key}")
                price_open = ob2.number_input("Unit Price (BDT)", min_value=0.0, step=1.0,
                                              value=float(item["price"]) if item is not None else 0.0,
                                              key=f"tx_price_open_{g}_{sl_key}")
                st.caption("Physical Stock = hate thaka poriman. ERP Stock = ERP-er balance. "
                           "Unit Price = proti ekok-er dam (khali/purono rakhle ager dam thakbe).")
            rate_in, rate_mode = None, None
            if ttype == "Supplier. Rec":
                # Shown ONLY for Supplier Receipt: the purchase rate becomes the item's Unit Price (so budget values are never blank).
                sl_key = item["sl_no"] if item is not None else 0
                cur_price = float(item["price"]) if item is not None else 0.0
                rc1, rc2 = st.columns(2, gap="small")
                rate_in = rc1.number_input("Purchase Rate (৳ / unit)", min_value=0.0, step=1.0, value=cur_price,
                                           key=f"tx_rate_{g}_{sl_key}")
                rate_mode = rc2.selectbox("Unit Price update", ["Latest purchase rate", "Weighted average", "Keep current price"],
                                          key=f"tx_ratemode_{g}")
                if item is not None:
                    if cur_price <= 0 and rate_in <= 0:
                        st.warning("⚠️ এই আইটেমের Unit Price এখনো 0 — Purchase Rate না দিলে এর Issue বাজেটে ধরা পড়বে না।")
                    elif cur_price > 0 and rate_in > 0 and abs(rate_in - cur_price) / cur_price > 0.25:
                        st.warning(f"⚠️ বর্তমান দাম ৳{cur_price:,.2f}, নতুন Purchase Rate ৳{rate_in:,.2f} "
                                   f"({(rate_in - cur_price) / cur_price * 100:+.0f}%) — দাম ঠিক আছে কিনা দেখে নিন।")
                    else:
                        st.caption(f"বর্তমান Unit Price ৳{cur_price:,.2f}। Purchase Rate বসালে নির্বাচিত নিয়মে Unit Price আপডেট হবে।")
            tx_date = dc.date_input("Date", value=date.today(), max_value=date.today(), key="tx_date")
            req_no = ""
            if ttype in ISSUE_TYPES:
                req_no = st.text_input("Requisition No. (SR No.)", value=st.session_state.get("last_req_no", ""),
                                       key=f"tx_req_{g}", placeholder="e.g. 1745 — স্লিপের SR নম্বর",
                                       help="একই রিকুইজিশন স্লিপের পরের আইটেমে নম্বরটা আবার লিখতে হবে না — আগেরটাই থাকবে।")
            verified, need_verif = False, False
            if item is not None and ttype in ISSUE_TYPES:
                need_verif, v_days = verification_needed(fac, item["sl_no"], tx_date)
                if need_verif:
                    st.warning(f"Physical verification required: {v_days} calendar days since the first unverified issue. Gaps count too; verify before saving.")
            verify_col, po_col = st.columns(2, gap="small")
            verified = verify_col.checkbox(
                "Physically verified" if need_verif else "Verified", key=f"tx_ver_{g}"
            )
            po_pending = po_col.checkbox(
                "ERP PO pending", key=f"tx_po_{g}",
                help="Track this transaction in ERP Audit → ERP PO Pending."
            )
            notes = st.text_input("Remarks", key=f"tx_notes_{g}", placeholder="Optional note")

            if item is not None:
                st.info(f"**{item['item_name']}** [{item['size'] or '-'}]  ·  Serial **{item['serial'] or '-'}**  ·  SL {item['sl_no']}  ·  "
                        f"ERP {item['prod_id']}  ·  Stock **{float(item['stock']):g}**  ·  "
                        f"Short: {max(float(item['erp']) - float(item['stock']), 0):g}")
                if ttype in ISSUE_TYPES:
                    _price_budget_warning(fac, item)
                if qty > 0:
                    if ttype in ISSUE_TYPES and need_verif and not verified:
                        blocked = True
                    if qty > float(item["stock"]) and ttype in ISSUE_TYPES:
                        shortage = qty - float(item["stock"])
                        other = find_same_in_other(item["prod_id"], item["item_name"], other_factory(fac), item["size"], need=shortage)
                        if other and float(other["stock"] or 0) >= shortage:
                            need_xfer = True
                            st.warning(f"⚠️ Stock short {shortage:g}. {other['factory_name']} theke auto-transfer hobe "
                                       f"({other['item_name']} [{other['prod_id']}], size {other['size'] or '-'}, stock {float(other['stock']):g}, "
                                       f"match: {other['level']} {int(round(float(other.get('score', 1.0)) * 100))}%).")
                            if other["level"] == "fuzzy":
                                st.info(f"ℹ️ নাম হুবহু এক নয় — এই item: **{item['item_name']}**, ওই unit-এর item: **{other['item_name']}** "
                                        f"(size একই: {item['size'] or '-'}, নামের মিল {int(round(float(other.get('score', 1.0)) * 100))}%). "
                                        "দুটো একই item কিনা দেখে নিয়ে নিচে confirm করুন।")
                            xfer_ok = st.checkbox("Transfer confirm kore issue korun", key=f"tx_xfer_{g}")
                        else:
                            st.error(f"Shortage {shortage:g} - other unit-e enough stock/same item nei.")
                            blocked = True
                    elif qty > float(item["stock"]) and ttype not in RECEIPT_TYPES and ttype != OPENING_TYPE:
                        st.error("Stock kom ache.")
                        blocked = True

            can_write = bool(st.session_state.get("user")) and st.session_state.get("role") != "Auditor" and not is_cons_view
            disabled = (item is None or blocked or (qty <= 0 and ttype != OPENING_TYPE)
                        or (need_xfer and not xfer_ok) or not can_write)
            if not can_write:
                st.caption("Save korte login + specific factory + non-Auditor role lage.")
            if st.button("💾 Save & Update Stock", type="primary", disabled=disabled, use_container_width=True, key="tx_save"):
                if st.session_state.get("tx_saved_gen") == g:
                    st.warning("Ei form already save hoyeche. Notun transaction-er jonno notun kore item select korun.")
                elif guard():
                    fresh = q(f"SELECT {INV_COLS} FROM inventory WHERE sl_no=%s AND factory_name=%s",
                              (item["sl_no"], item["factory_name"]))
                    if not fresh:
                        st.error("Item ar paoa jacche na. Page refresh kore abar select korun.")
                    else:
                        item = fresh[0]   # always work with the live stock, never a stale copy
                        if is_duplicate_tx(item["factory_name"], item["sl_no"], ttype, qty, tx_date.strftime(DATE_FMT),
                                           st.session_state.get("user", ""), notes, req_no if ttype in ISSUE_TYPES else ""):
                            st.error("🚫 Duplicate block: ekdom ek-i transaction ei matro save hoyeche. "
                                     "Quantity / remarks bodle ba kichukkhon por abar korun.")
                        elif save_transaction(fac, item, qty, ttype, tx_date, notes, verified, xfer_ok,
                                              supplier.strip(), challan.strip(), po_pending, erp_open=erp_open,
                                              price_open=price_open, rate=rate_in, rate_mode=rate_mode, req_no=req_no):
                            if ttype in ISSUE_TYPES:
                                st.session_state["last_req_no"] = req_no.strip()
                            st.session_state["tx_saved_gen"] = g
                            st.session_state["tx_gen"] = g + 1
                            done("✅ Transaction saved, stock updated. Form reset hoyeche - porer transaction-er jonno ready.")

    with left:
        _tx_entry_form()

    @_frag   # searching the recent list re-runs ONLY this block
    def _tx_recent_panel():
        st.markdown('<div class="section-title">Recent Transactions</div>', unsafe_allow_html=True)
        rs = st.text_input("🔍 Search transactions (Item / Serial / ERP / SL / Officer)", key="tx_recent_search")
