# ============================================================
#  OPENING CHECK (new, ADDITIVE ONLY): Excel opening file vs software stock when the Excel has NO ERP code.
#  Names are matched exactly first, then by similarity ("Bearing 6206" ~ "Bearing-6206"). Nothing is changed in stock.
# ============================================================
def _oc_norm(name, size=""):
    t = f"{name or ''} {size or ''}".lower()
    t = re.sub(r"[^a-z0-9.]+", " ", t)
    return re.sub(r"\s+", " ", t).strip()


def _oc_numbers(t):
    return sorted(re.findall(r"\d+(?:\.\d+)?", t))


def _oc_score(a, b):
    ta, tb = a.split(), b.split()
    r1 = difflib.SequenceMatcher(None, a, b, autojunk=False).ratio()
    r2 = difflib.SequenceMatcher(None, " ".join(sorted(ta)), " ".join(sorted(tb)), autojunk=False).ratio()
    return max(r1, r2)


def _oc_typo_hint(f, s_):
    """File qty vs software qty: looks like a typing slip (6 -> 60, 12 -> 21, 105 -> 15 ...)?"""
    try:
        if abs(f - round(f)) > 1e-9 or abs(s_ - round(s_)) > 1e-9:
            return ""
        a, b = str(int(round(f))), str(int(round(s_)))
    except Exception:
        return ""
    if a == b:
        return ""
    if f > 0 and s_ > 0 and (abs(s_ / f - 10) < 1e-9 or abs(f / s_ - 10) < 1e-9):
        return "⚠️ ১০ গুণ — টাইপের ভুল হতে পারে"
    if len(a) == len(b) and sorted(a) == sorted(b):
        return "⚠️ অঙ্ক উল্টে গেছে — টাইপের ভুল হতে পারে"
    if abs(len(a) - len(b)) == 1:
        lo, hi = (a, b) if len(a) < len(b) else (b, a)
        if any(hi[:i] + hi[i + 1:] == lo for i in range(len(hi))):
            return "⚠️ একটা অঙ্ক বেশি/কম — টাইপের ভুল হতে পারে"
    return ""


def _oc_size_conflict(a, b):
    """Both items HAVE a size and the sizes differ -> they are different items (V Belt-A A-54 vs V Belt-A A-78)."""
    x, y = norm_size(a), norm_size(b)
    return bool(x and y and x != y)


def opening_check_build(fac, file_rows, min_score, ignore_code=False):
    """Order of matching: (1) ERP code - but ONLY if the item names also agree, (2) identical name(+size), (3) similar name.
    A code that points to a clearly different item is reported as a code conflict instead of being trusted."""
    db_rows = recon_db_rows(fac)
    moves = {int(r["sl_no"]): int(r["n"]) for r in q_c(
        """SELECT sl_no, COUNT(*) AS n FROM transactions WHERE factory_name=%s AND trans_type<>%s GROUP BY sl_no""",
        (fac, OPENING_TYPE))}
    dbn_all = {r["sl_no"]: _oc_norm(r["item_name"], r["size"]) for r in db_rows}
    by_code, by_name = {}, {}
    for r in db_rows:
        c = str(r["prod_id"] or "").strip().lower()
        if not is_blank_code(c):
            by_code.setdefault(c, []).append(r)
        by_name.setdefault(norm_name(r["item_name"]), []).append(r)
    used_db, assigned, conflict = set(), {}, {}      # conflict: file idx -> software row the CODE points to
    fns = [_oc_norm(fr["name"], fr["size"]) for fr in file_rows]
    fcode = [("" if ignore_code else str(fr["code"] or "").strip()) for fr in file_rows]
    # (1) ERP code, verified against the name
    for i, fr in enumerate(file_rows):
        c = fcode[i].lower()
        if is_blank_code(c) or c not in by_code:
            continue
        free = [r for r in by_code[c] if r["sl_no"] not in used_db]
        if not free:
            continue
        r0 = free[0]
        sc = _oc_score(fns[i], dbn_all[r0["sl_no"]]) if fns[i] else 1.0
        if (sc >= 0.75 and _oc_numbers(fns[i]) == _oc_numbers(dbn_all[r0["sl_no"]])
                and not _oc_size_conflict(fr["size"], r0["size"])):
            assigned[i] = (r0, "ERP code + নাম মিল", 1.0)
            used_db.add(r0["sl_no"])
        else:
            conflict[i] = r0
    # (2) identical name (size narrows the choice)
    for i, fr in enumerate(file_rows):
        if i in assigned or not fr["name"]:
            continue
        cands = by_name.get(norm_name(fr["name"]), [])
        ns = norm_size(fr["size"])
        if ns:
            same = [c for c in cands if norm_size(c["size"]) == ns]
            blank = [c for c in cands if not norm_size(c["size"])]
            pool = same or blank                     # a different size is NEVER accepted
            label = "হুবহু নাম" if same else "নাম মিল (সফটওয়্যারে সাইজ নেই)"
        else:
            sizes = {norm_size(c["size"]) for c in cands}
            pool = cands if len(sizes) <= 1 else []   # several sizes in software and none in Excel -> ambiguous, not guessed
            label = "হুবহু নাম" if (pool and not norm_size(pool[0]["size"])) else "নাম মিল (Excel-এ সাইজ নেই)"
        free = [c for c in pool if c["sl_no"] not in used_db]
        if free:
            assigned[i] = (free[0], label, 1.0)
            used_db.add(free[0]["sl_no"])
    # (3) similar name for the rest (token index keeps it fast for thousands of rows)
    dbn = [(r, dbn_all[r["sl_no"]]) for r in db_rows if r["sl_no"] not in used_db]
    inv = {}
    for di, (_r, nm) in enumerate(dbn):
        for tk in set(nm.split()):
            if len(tk) >= 2:
                inv.setdefault(tk, []).append(di)
    cand_pairs, best_any = [], {}
    for i in range(len(file_rows)):
        if i in assigned:
            continue
        fn = fns[i]
        votes = {}
        for tk in set(fn.split()):
            lst = inv.get(tk, [])
            if 0 < len(lst) <= 400:
                w = 1.0 / len(lst)
                for di in lst:
                    votes[di] = votes.get(di, 0.0) + w
        fnum = _oc_numbers(fn)
        for di in sorted(votes, key=votes.get, reverse=True)[:15]:
            sc = _oc_score(fn, dbn[di][1])
            same_num = (fnum == _oc_numbers(dbn[di][1])) and not _oc_size_conflict(file_rows[i]["size"], dbn[di][0]["size"])
            if i not in best_any or sc > best_any[i][1]:
                best_any[i] = (di, sc, same_num)
            if sc >= min_score and same_num:
                cand_pairs.append((sc, i, di))
    for sc, i, di in sorted(cand_pairs, reverse=True):
        if i in assigned or dbn[di][0]["sl_no"] in used_db:
            continue
        assigned[i] = (dbn[di][0], f"কাছাকাছি নাম ({sc * 100:.0f}%)", sc)
        used_db.add(dbn[di][0]["sl_no"])
    out = []
    for i, fr in enumerate(file_rows):
        fq = float(fr["qty"])
        code_note = ""
        cf = conflict.get(i)
        if cf is not None:
            code_note = f"⚠️ Excel-এর কোড {fcode[i]} সফটওয়্যারে অন্য আইটেমের: {cf['item_name']} [{cf['size'] or '-'}]"
        if i in assigned:
            m, label, sc = assigned[i]
            if not code_note and fcode[i] and not is_blank_code(fcode[i]) and str(m["prod_id"] or "").strip().lower() != fcode[i].lower():
                code_note = f"⚠️ Excel কোড {fcode[i]} ≠ সফটওয়্যার কোড {m['prod_id']}"
            sp = float(m["phys"])
            diff = sp - fq
            if abs(diff) < 1e-6:
                res = "Match" if label.startswith(("ERP code", "হুবহু")) else "Match (নাম কাছাকাছি — দেখে নিন)"
            else:
                res = "Qty differs"
            out.append({"Result": res, "File Item": fr["name"], "File Size": fr["size"], "File Qty": fq,
                        "Software Item": m["item_name"], "Software Size": m["size"], "SL No": int(m["sl_no"]),
                        "ERP Code": m["prod_id"], "Software Physical": sp, "Software − File": diff,
                        "Name match": label, "Code note": code_note,
                        "Hint": _oc_typo_hint(fq, sp) if res == "Qty differs" else "",
                        "Moves since opening": moves.get(int(m["sl_no"]), 0)})
        else:
            near = ""
            if i in best_any and best_any[i][1] >= 0.5:
                di, sc, same_num = best_any[i]
                r = dbn[di][0]
                near = f"{r['item_name']} [{r['size'] or '-'}] · SL {r['sl_no']} · {sc * 100:.0f}%" + ("" if same_num else " · সাইজ/সংখ্যা আলাদা")
            out.append({"Result": "Not in software", "File Item": fr["name"], "File Size": fr["size"], "File Qty": fq,
                        "Software Item": "", "Software Size": "", "SL No": None, "ERP Code": "", "Software Physical": None,
                        "Software − File": None, "Name match": "মেলেনি", "Code note": code_note,
                        "Hint": ("সবচেয়ে কাছের: " + near) if near else "", "Moves since opening": 0})
    for r in db_rows:
        if r["sl_no"] in used_db:
            continue
        sp = float(r["phys"])
        if abs(sp) < 1e-9:
            continue
        out.append({"Result": "Not in file", "File Item": "", "File Size": "", "File Qty": None,
                    "Software Item": r["item_name"], "Software Size": r["size"], "SL No": int(r["sl_no"]),
                    "ERP Code": r["prod_id"], "Software Physical": sp, "Software − File": sp, "Name match": "মেলেনি",
                    "Code note": "", "Hint": "", "Moves since opening": moves.get(int(r["sl_no"]), 0)})
    return pd.DataFrame(out)

def opening_check_panel(default_fac):
    with st.expander("🔎 Opening Check — Excel-এ ERP code না থাকলে নাম মিলিয়ে (কাছাকাছি নামসহ)", expanded=False):
        st.caption("প্রথম দিনের ওপেনিং Excel দিন। অ্যাপ নাম দিয়ে মেলাবে (হুবহু, না মিললে কাছাকাছি নাম) এবং যেখানে সংখ্যা আলাদা সেখানে "
                   "কেন আলাদা সেটা দেখাবে — যেমন ৬ এর জায়গায় ৬০ বসে গেলে ধরিয়ে দেবে। স্টকে কিছু বদলায় না। "
                   "যেসব আইটেমে ওপেনিংয়ের পর Issue/Receipt হয়ে গেছে সেগুলো শেষ কলামে দেখা যাবে।")
        c1, c2 = st.columns(2)
        fac = c1.selectbox("Factory", FACTORIES, index=FACTORIES.index(default_fac) if default_fac in FACTORIES else 0, key="oc_fac")
        min_pct = c2.slider("নাম কতটা মিললে 'কাছাকাছি' ধরবেন (%)", 70, 98, 85, key="oc_pct")
        ignore_code = st.checkbox("Excel-এর কোড কলাম ব্যবহার করবেন না — শুধু নাম দিয়ে মেলান", key="oc_ignore_code",
                                  help="Excel-এর 'Code' কলামটা আসল ERP code না হলে বা ভুল হলে এটা টিক দিন।")
        up = st.file_uploader("প্রথম দিনের ওপেনিং Excel / CSV", type=["xlsx", "xls", "csv"], key="oc_file")
        if not up:
            return
        raw = read_any(up)
        cols = recon_detect(raw)
        if cols is None or not cols["name"]:
            st.error("Quantity ও Item Name কলাম পাওয়া যায়নি।")
            st.write("Columns found:", list(raw.columns))
            return
        st.caption(f"পাওয়া কলাম → Item: {cols['name']} | Size: {cols['size'] or '—'} | Quantity: {cols['qty']} | ERP code: {cols['code'] or '—'}")
        file_rows, skipped = recon_file_rows(raw, cols)
        st.caption(f"ব্যবহারযোগ্য সারি: {len(file_rows):,} | বাদ: {skipped}")
        if st.button("▶ Opening Check চালান", type="primary", key="oc_run", disabled=not file_rows):
            with st.spinner("নাম মেলানো হচ্ছে ..."):
                st.session_state["oc_result"] = {"fac": fac, "file": up.name, "df": opening_check_build(fac, file_rows, min_pct / 100.0, ignore_code)}
        res = st.session_state.get("oc_result")
        if not res or res["fac"] != fac:
            st.info("ওপরে 'Opening Check চালান' চাপুন।")
            return
        df = res["df"]
        counts = df["Result"].value_counts()
        mc = st.columns(5)
        mc[0].metric("Match", int(counts.get("Match", 0)))
        mc[1].metric("Match (নাম কাছাকাছি)", int(counts.get("Match (নাম কাছাকাছি — দেখে নিন)", 0)))
        mc[2].metric("Qty differs", int(counts.get("Qty differs", 0)))
        mc[3].metric("Not in software", int(counts.get("Not in software", 0)))
        mc[4].metric("Not in file", int(counts.get("Not in file", 0)))
        cn = int((df["Code note"].astype(str) != "").sum())
        if cn:
            st.error(f"{cn}টি সারিতে Excel-এর ERP code আর সফটওয়্যারের code একই আইটেম বোঝাচ্ছে না (Code note কলাম)। "
                     "Excel-এর 'Code' কলামটা আসলেই ERP code কি না দেখুন; না হলে ওপরের টিকবক্স দিয়ে শুধু নামে মেলান।")
        typo = int((df["Hint"].astype(str).str.startswith("⚠️")).sum())
        if typo:
            st.warning(f"{typo}টি আইটেমে সংখ্যায় টাইপের ভুলের মতো দেখাচ্ছে (⚠️ Hint কলাম)।")
        if int((df["Moves since opening"] > 0).sum()):
            st.info("'Moves since opening' > 0 মানে ওই আইটেমে ওপেনিংয়ের পর Issue/Receipt হয়েছে — সেখানে অমিল স্বাভাবিক হতে পারে।")
        opts = ["সব অমিল", "Qty differs", "Match (নাম কাছাকাছি — দেখে নিন)", "Not in software", "Not in file", "Match"]
        pick = st.selectbox("দেখান", opts, key="oc_filter")
        view = df[df["Result"] != "Match"] if pick == "সব অমিল" else df[df["Result"] == pick]
        st.dataframe(view, hide_index=True, use_container_width=True, height=420, column_config={
            "File Qty": st.column_config.NumberColumn(format="%.2f"),
            "Software Physical": st.column_config.NumberColumn(format="%.2f"),
            "Software − File": st.column_config.NumberColumn(format="%.2f")})
        export_buttons(df, "opening_check_result")


def tab_stock_report():
    st.title("Stock Report & ERP Reconciliation")
    st.caption("ERP Stock QTY, Physical Stock QTY, Stock Balance and values for the selected factory.")
    fac, fsql, fp = FAC, FSQL, FP

    with st.expander("⚠️ Reset All Stock to Zero (Fresh Start for 1-by-1 Entry)"):
        st.warning("This will set ERP Stock and Physical Stock to 0 for all items in this factory. Item names will remain intact.")
        reset_pw = st.text_input("Store Manager Password", type="password", key="sr_reset_pw")
        reset_conf = confirm_box("sr_reset_conf", "I confirm I want to set all stock quantities to Zero.")
        if st.button("Set All Stock to 0", type="primary", key="sr_reset_btn"):
            if not verify_manager_password(reset_pw):
                st.error("Incorrect Manager Password.")
            elif not reset_conf:
                st.error("Please confirm by checking the box.")
            elif reset_all_stock_to_zero(fac):
                done("All stock balances have been reset to Zero.")

    st_items = qdf_c(f"""SELECT factory_name, sl_no, COALESCE(serial_no,'') AS serial_no, prod_id, item_name,
                       COALESCE(size,'') AS size, department, category,
                       COALESCE(erp_stock,0) AS erp_stock, COALESCE(current_stock,0) AS current_stock,
                       COALESCE(unit_price,0) AS unit_price, COALESCE(NULLIF(unit_name,''),'Pcs') AS unit_name
                       FROM inventory WHERE 1=1{fsql} ORDER BY factory_name, sl_no""", fp)

    if st_items.empty:
        st.info("No items found in inventory.")
    else:
        st_items["ERP Stock QTY"] = st_items["erp_stock"]
        st_items["Physical Stock QTY"] = st_items["current_stock"]
        st_items["Stock Balance"] = st_items["current_stock"]
        st_items["Stock Value"] = st_items["current_stock"] * st_items["unit_price"]
        st_items["ERP Balance Value"] = st_items["erp_stock"] * st_items["unit_price"]
        st_items["Physical Balance Value"] = st_items["current_stock"] * st_items["unit_price"]
        st_items["variance"] = st_items["Physical Stock QTY"] - st_items["ERP Stock QTY"]
        st_items["Status"] = st_items.variance.apply(
            lambda v: "Match" if abs(v) < 1e-9 else ("Excess" if v > 0 else "Shortage"))

        _d1, _d2, _plbl = report_period("sr", default="এই মাস", label="📅 Received / Issued সময়কাল (মাস / তারিখ)")
        _psql, _pp = period_sql("t.date", _d1, _d2)
        _mv = qdf_c(f"""SELECT t.factory_name, t.sl_no,
                    COALESCE(SUM(CASE WHEN t.trans_type IN ('Supplier. Rec','Internal Rec') THEN t.qty ELSE 0 END),0) AS p_recv,
                    COALESCE(SUM(CASE WHEN t.trans_type IN ('Issued','Internal Issue') THEN t.qty ELSE 0 END),0) AS p_issue
                    FROM transactions t
                    WHERE t.trans_type IN ('Issued','Internal Issue','Supplier. Rec','Internal Rec'){fw(fac, 't.')[0]}{_psql}
                    GROUP BY t.factory_name, t.sl_no""", fp + _pp)
        st_items = st_items.merge(_mv, on=["factory_name", "sl_no"], how="left")
