def tab_issue_ledger():
    iss = qdf_c(f"""SELECT t.id, t.date, t.time, t.factory_name, t.item_name, COALESCE(i.size,'') AS size,
                  COALESCE(i.serial_no,'') AS serial_no, t.prod_id, t.sl_no, t.qty,
                  COALESCE(i.unit_price,0) AS unit_price, t.officer_name, t.trans_type, t.notes, t.verification_status,
                  COALESCE(t.po_pending_flag,'') AS po_flag, COALESCE(t.req_no,'') AS req_no
                  FROM transactions t LEFT JOIN inventory i ON t.sl_no=i.sl_no AND t.factory_name=i.factory_name
                  WHERE t.trans_type IN ('Issued','Internal Issue'){fw(FAC, 't.')[0]} ORDER BY t.id DESC""", FP)
    if not iss.empty:
        iss["total_value"] = iss.qty * iss.unit_price
        iss["type"] = iss.trans_type.map(lambda c: TRANS_LABELS.get(c, c))
        iss["erp_status"] = iss.notes.fillna("").apply(lambda n: "ERP PO Pending" if "Pending" in n else "ERP GRN Completed")
        iss.loc[iss["po_flag"] == "Pending", "erp_status"] = "ERP PO Pending"   # tagged in Transactions / here
        iss.loc[iss["po_flag"] == "Done", "erp_status"] = "ERP Entry Done"
        iss["_dt"] = pd.to_datetime(iss["date"].apply(parse_date), errors="coerce")

    st.markdown('<div class="section-title">Search & Filter Issues</div>', unsafe_allow_html=True)
    if iss.empty:
        st.info("Issue record nei.")
        st.dataframe(iss, hide_index=True, use_container_width=True)
        return

    month_names = list(calendar.month_name)[1:]
    years = sorted({int(y) for y in iss["_dt"].dt.year.dropna()}, reverse=True)
    with st.container(border=True):
        f1, f2, f3 = st.columns([3, 1, 1])
        term = f1.text_input("🔍 Search (Item Name / Serial No / ERP Code / SL No / Officer / Factory)", key="il_search",
                             placeholder="e.g. Spherical Roller Bearing, KW-001 ...")
        mon = f2.selectbox("Month", ["All"] + month_names, key="il_month")
        yr = f3.selectbox("Year", ["All"] + [str(y) for y in years], key="il_year")
        use_rng = st.checkbox("Use exact date range (From - To)", key="il_use_rng")
        d_from = d_to = None
        if use_rng:
            r1, r2 = st.columns(2)
            d_from = r1.date_input("From", value=date.today().replace(day=1), key="il_from")
            d_to = r2.date_input("To", value=date.today(), key="il_to")

    view = iss
    t = term.strip().lower()
    if t:
        scols = ["item_name", "serial_no", "prod_id", "size", "officer_name", "factory_name", "notes", "req_no"]
        m = view[scols].fillna("").astype(str).apply(lambda c: c.str.lower().str.contains(t, regex=False)).any(axis=1)
        view = view[m | (view["sl_no"].astype(str).str.strip() == t)]
    if mon != "All":
        view = view[view["_dt"].dt.month == month_names.index(mon) + 1]
    if yr != "All":
        view = view[view["_dt"].dt.year == int(yr)]
    if use_rng:
        if d_from > d_to:
            st.error("'From' date 'To' date-er age hote hobe.")
        else:
            view = view[(view["_dt"] >= pd.Timestamp(d_from)) & (view["_dt"] < pd.Timestamp(d_to) + pd.Timedelta(days=1))]

    mc = st.columns(5)
    mc[0].metric("Total Issued Qty", f"{view.qty.sum():g}")
    mc[1].metric("Issue Entries", len(view))
    mc[2].metric("Distinct Items", view[["factory_name", "sl_no"]].drop_duplicates().shape[0])
    mc[3].metric("Issued Value (৳)", f"{view.total_value.sum():,.0f}")
    _srs = view[view["req_no"].astype(str).str.strip() != ""]["req_no"].astype(str).str.strip()
    mc[4].metric("Requisitions (SR)", f"{_srs.nunique():,}",
                 f"{len(_srs):,} আইটেম-লাইন ইস্যু" if len(_srs) else None, delta_color="off")
    if view.empty:
        st.info("Ei filter-e kono issue record nei.")
        return

    _tab = lazy_tab_select(["📋 Issue Details", "📅 Date-wise Summary", "📦 Item-wise Summary", "✏️ ERP Balance Update", "🏷 Tag ERP PO Pending", "🧾 Requisition-wise"], "lz_issue")
    if _tab == 0:
        detail = view.sort_values(["_dt", "id"], ascending=False)[
            ["id", "date", "time", "req_no", "factory_name", "serial_no", "prod_id", "sl_no", "item_name", "size", "qty", "unit_price",
             "total_value", "officer_name", "type", "verification_status", "erp_status", "notes"]]
        st.dataframe(detail, hide_index=True, use_container_width=True, height=380)
        export_buttons(detail, "issue_ledger")
    if _tab == 1:
        dd = view[view["_dt"].notna()]
        if dd.empty:
            st.info("Valid date record nei.")
        else:
            day = dd["_dt"].dt.normalize()
            daily = dd.groupby(day).agg(entries=("id", "count"), qty=("qty", "sum"), value=("total_value", "sum")).reset_index()
            daily["Date"] = daily["_dt"].dt.strftime(DATE_FMT)
            daily = daily[["Date", "entries", "qty", "value"]]
            daily.columns = ["Date", "Issue Entries", "Qty Issued", "Value (৳)"]
            st.markdown("**Date-wise total issued**")
            st.dataframe(daily, hide_index=True, use_container_width=True)
            export_buttons(daily, "issue_datewise_summary")
            st.markdown("**Date × Item × Factory**")
            grp = dd.groupby([day, "item_name", "factory_name"], as_index=False).qty.sum()
            grp["Date"] = grp["_dt"].dt.strftime(DATE_FMT)
            grp = grp[["Date", "item_name", "factory_name", "qty"]]
            grp.columns = ["Date", "Item Name", "Factory", "Qty Issued"]
            st.dataframe(grp, hide_index=True, use_container_width=True)
            export_buttons(grp, "issue_date_item_factory")
    if _tab == 2:
        items = (view.groupby(["factory_name", "item_name", "size", "serial_no", "prod_id"], as_index=False)
                 .agg(entries=("id", "count"), qty=("qty", "sum"), value=("total_value", "sum"))
                 .sort_values("qty", ascending=False))
        items.columns = ["Factory", "Item Name", "Size", "Serial No", "ERP Code", "Issue Entries", "Qty Issued", "Value (৳)"]
        st.dataframe(items, hide_index=True, use_container_width=True)
        export_buttons(items, "issue_item_summary")
    if _tab == 3:
        il_erp_update_panel(view.groupby(["factory_name", "sl_no"], as_index=False).qty.sum())
    if _tab == 4:
        il_po_tag_panel(view.sort_values("id", ascending=False)[
            ["id", "date", "factory_name", "item_name", "size", "qty", "officer_name", "po_flag"]].head(300))
    if _tab == 5:
        _ls = view.copy()
        _ls["req_no"] = _ls["req_no"].astype(str).str.strip()
        with_sr = _ls[_ls["req_no"] != ""]
        no_sr = _ls[_ls["req_no"] == ""]
        r1, r2, r3, r4 = st.columns(4)
        r1.metric("মোট Requisition (SR)", f"{with_sr['req_no'].nunique():,}")
        r2.metric("মোট ইস্যু হওয়া আইটেম-লাইন", f"{len(with_sr):,}")
        r3.metric("আলাদা আইটেম", f"{with_sr[['factory_name', 'sl_no']].drop_duplicates().shape[0]:,}")
        r4.metric("SR নম্বর ছাড়া ইস্যু", f"{len(no_sr):,}")
        if with_sr.empty:
            st.info("এই ফিল্টারে SR নম্বরসহ কোনো ইস্যু নেই। Transactions-এ Issue করার সময় 'Requisition No. (SR No.)' লিখুন।")
        else:
            srt = (with_sr.groupby(["req_no"], as_index=False)
                   .agg(Date=("_dt", "max"), Lines=("id", "count"), Items=("sl_no", "nunique"), Qty=("qty", "sum"),
                        Value=("total_value", "sum"), Officer=("officer_name", lambda x: ", ".join(sorted(set(map(str, x)))))))
            srt = srt.sort_values(["Date", "req_no"], ascending=False)
            srt["Date"] = srt["Date"].dt.strftime(DATE_FMT)
            srt.columns = ["SR No.", "Date", "Item lines issued", "Distinct items", "Total qty", "Value (৳)", "Officer"]
            st.dataframe(srt, hide_index=True, use_container_width=True, height=420,
                         column_config={"Value (৳)": st.column_config.NumberColumn(format="%.0f")})
            export_buttons(srt, "issue_requisition_wise")
            st.caption("'Item lines issued' = ওই SR-এ কতগুলো আইটেম লাইন ইস্যু হয়েছে। ওপরের তারিখ/মাস ফিল্টার দিয়ে একদিনের সব SR মিলিয়ে দেখুন।")
    tx_manager_panel(view[["id", "item_name", "qty", "date"]], "il", "🔐 Manager: Delete / Edit an issue entry")


def ensure_erp_track_columns():
    """Adds two columns that remember when each item's ERP balance was last updated from the Issue Ledger.
    On first creation, issues dated before today count as 'up to date' and today's issues start as pending. Additive; no existing value is changed."""
    if st.session_state.get("_erp_track_ready") or _once_flags().get("erp_track"):
        return
    conn = get_conn()
    try:
        with conn.cursor() as cur:
            cur.execute("""SELECT 1 FROM information_schema.columns
                           WHERE table_name='inventory' AND column_name='erp_upto_tx'""")
            existed = cur.fetchone() is not None
            cur.execute("ALTER TABLE inventory ADD COLUMN IF NOT EXISTS erp_upto_tx INTEGER")
            cur.execute("ALTER TABLE inventory ADD COLUMN IF NOT EXISTS erp_updated_at TEXT")
            if not existed:
                # Issues dated before today count as already handled; today's issues start as pending.
                cur.execute("""UPDATE inventory i SET erp_upto_tx=(SELECT COALESCE(MAX(t.id),0) FROM transactions t
                               WHERE t.sl_no=i.sl_no AND t.factory_name=i.factory_name
                                 AND t.trans_type IN ('Issued','Internal Issue') AND t.date <> %s)""",
                            (local_now().strftime(DATE_FMT),))
        conn.commit()
        st.session_state["_erp_track_ready"] = True
        _once_flags()["erp_track"] = True
    except Exception:
        conn.rollback()
        raise


@tx
def save_erp_balances(changes):
    """changes: list of dicts (factory, sl_no, code, name, old, new). One UPDATE for all rows + one audit entry.
    Each saved item is marked 'ERP updated up to the latest issue', so it leaves the pending list."""
    if not changes:
        return 0
    marks = ",".join(["(%s,%s,%s)"] * len(changes))
    params = [local_now().strftime("%d-%b-%Y %I:%M %p")]
    for c in changes:
        params += [int(c["sl_no"]), str(c["factory"]), float(c["new"])]
    run(f"""UPDATE inventory i SET erp_stock=v.erp, erp_updated_at=%s,
            erp_upto_tx=(SELECT COALESCE(MAX(t.id),0) FROM transactions t
                         WHERE t.sl_no=i.sl_no AND t.factory_name=i.factory_name
                           AND t.trans_type IN ('Issued','Internal Issue'))
            FROM (VALUES {marks}) AS v(sl, fac, erp)
            WHERE i.sl_no=v.sl AND i.factory_name=v.fac""", params)
    detail = "; ".join(f"{c['factory']}: {c['code']} {c['old']:g}->{c['new']:g}" for c in changes)
    audit("ERP_BALANCE_UPDATE", f"{len(changes)} item(s) from Issue Ledger: " + detail[:1500])
    return len(changes)


@_fragment
def il_erp_update_panel(issued):
    """One row per item. Click an ERP balance, type the new value, save - shows the real Short / Excess
    (Physical - ERP). A fragment: editing cells does not reload the whole page."""
    try:
        ensure_erp_track_columns()
    except Exception as e:
        st.error(f"ERP update tracking could not be prepared: {e}")
        return
    mode = st.radio("Show", ["⏳ ERP update pending", "📋 All issued items (filters above)"], horizontal=True,
                    key="il_erp_mode")
    pending_mode = mode.startswith("⏳")
    if pending_mode:
        st.caption("Items that were issued **after** their ERP balance was last updated here (all dates). "
                   "Enter the ERP balance and Save - the item leaves this list. If the ERP balance is already "
                   "correct, just tick **Done** and Save.")
        fsql_i, fp_i = fw(FAC, "i.")
        base = qdf(f"""SELECT i.factory_name, i.sl_no, i.prod_id, i.item_name, COALESCE(i.size,'') AS size,
                       COALESCE(i.current_stock,0) AS phys, COALESCE(i.erp_stock,0) AS erp,
                       COALESCE(i.erp_updated_at,'') AS upd, SUM(t.qty) AS qty
                       FROM inventory i JOIN transactions t ON t.sl_no=i.sl_no AND t.factory_name=i.factory_name
                       WHERE t.trans_type IN ('Issued','Internal Issue') AND t.id > COALESCE(i.erp_upto_tx,0){fsql_i}
                       GROUP BY i.factory_name, i.sl_no, i.prod_id, i.item_name, i.size, i.current_stock,
                                i.erp_stock, i.erp_updated_at
                       ORDER BY SUM(t.qty) DESC""", fp_i)
        qty_label = "Issued since last ERP update"
        if base.empty:
            st.success("Nothing pending - every issued item has its ERP balance updated.")
            return
    else:
        st.caption("Every item issued in the period selected above - one row per item. Click a value in "
                   "**ERP balance**, type the ERP's balance, then Save. Short / Excess = Physical stock − ERP balance.")
        if issued.empty:
            st.info("No issued items for this filter.")
            return
        inv = qdf(f"""SELECT factory_name, sl_no, prod_id, item_name, COALESCE(size,'') AS size,
                      COALESCE(current_stock,0) AS phys, COALESCE(erp_stock,0) AS erp,
                      COALESCE(erp_updated_at,'') AS upd
                      FROM inventory WHERE sl_no = ANY(%s){FSQL}""", [[int(x) for x in issued["sl_no"].unique()]] + FP)
        base = issued.merge(inv, on=["factory_name", "sl_no"], how="inner").sort_values("qty", ascending=False)
        qty_label = "Issued qty"
        if base.empty:
            st.info("These issued items are no longer in the inventory.")
            return
    if len(base) > 400:
        st.caption(f"Showing the 400 most-issued items of {len(base)}.")
        base = base.head(400)
    df = pd.DataFrame({"Factory": base.factory_name.values, "SL No": base.sl_no.values, "ERP Code": base.prod_id.values,
                       "Item": base.item_name.values, "Size": base["size"].values,
                       qty_label: base.qty.astype(float).values,
                       "Physical stock": base.phys.astype(float).values, "ERP balance": base.erp.astype(float).values,
                       "ERP last updated": base.upd.values})
    df["Short / Excess"] = df["Physical stock"] - df["ERP balance"]
    df["Result"] = df["Short / Excess"].apply(lambda d: "✅ Match" if abs(d) < 1e-9 else ("🔻 Short" if d < 0 else "🔺 Excess"))
    df["Done"] = False
    gen = st.session_state.get("il_erp_gen", 0)
    edited = st.data_editor(
        df, hide_index=True, use_container_width=True, height=420, key=f"il_erp_ed_{gen}_{int(pending_mode)}",
        disabled=[c for c in df.columns if c not in ("ERP balance", "Done")],
        column_config={
            "ERP balance": st.column_config.NumberColumn("ERP balance ✏️", format="%.2f", step=1.0, required=True),
            qty_label: st.column_config.NumberColumn(format="%.2f"),
            "Physical stock": st.column_config.NumberColumn(format="%.2f"),
            "Short / Excess": st.column_config.NumberColumn(format="%+.2f"),
            "Done": st.column_config.CheckboxColumn("Done ✔", help="ERP balance is already correct - mark as updated"),
        })
    new = pd.to_numeric(edited["ERP balance"], errors="coerce")
    value_changed = new.notna() & ((new - df["ERP balance"]).abs() > 1e-9)
    ticked = edited["Done"].astype(bool) & new.notna()
    to_save = value_changed | ticked
    n = int(to_save.sum())
    if int(value_changed.sum()):
        pv = pd.DataFrame({"Item": df.loc[value_changed, "Item"], "Physical stock": df.loc[value_changed, "Physical stock"],
                           "New ERP balance": new[value_changed],
                           "Short / Excess": df.loc[value_changed, "Physical stock"] - new[value_changed]})
        st.markdown(f"**{int(value_changed.sum())} balance change(s) not saved yet** - preview of the new Short / Excess:")
        st.dataframe(pv, hide_index=True, use_container_width=True)
    if st.button(f"💾 Save ERP balances ({n})", key="il_erp_save", type="primary", disabled=(n == 0),
                 use_container_width=True) and guard():
        changes = [{"factory": df.at[i, "Factory"], "sl_no": df.at[i, "SL No"], "code": df.at[i, "ERP Code"],
                    "name": df.at[i, "Item"], "old": float(df.at[i, "ERP balance"]), "new": float(new[i])}
                   for i in df.index[to_save]]
        if save_erp_balances(changes):
            st.session_state["il_erp_gen"] = gen + 1
            done(f"ERP balance updated for {len(changes)} item(s).")


@tx
def set_po_pending_flags(ids_on, ids_off):
    """Tags / un-tags saved Issue entries as 'ERP PO Pending' (same flag the Transactions tick box sets, so they also
    appear in ERP Audit -> ERP PO Pending and can be closed there with 'Mark as Done')."""
    if ids_on:
        run("""UPDATE transactions SET po_pending_flag='Pending', po_pending_date=%s
               WHERE id = ANY(%s) AND trans_type IN ('Issued','Internal Issue')""",
            (local_now().strftime(DATE_FMT), [int(i) for i in ids_on]))
    if ids_off:
        run("""UPDATE transactions SET po_pending_flag='', po_pending_date=NULL
               WHERE id = ANY(%s) AND po_pending_flag='Pending'""", ([int(i) for i in ids_off],))
    audit("ERP_PO_TAG", f"Issue Ledger: tagged {sorted(int(i) for i in ids_on)}, untagged {sorted(int(i) for i in ids_off)}")
    return True


@_fragment
def il_po_tag_panel(rows):
    """Tick the issue entries that were never entered in the ERP (PO pending) - found later while updating balances."""
    st.caption("While updating ERP balances you may find an issue that was never entered in the ERP (PO pending). "
               "Tick **ERP PO Pending** on that entry and Save. It then shows in ERP Audit → ERP PO Pending, "
               "where it can be closed with 'Mark as Done' once the ERP entry is made. Latest 300 entries of the filter are listed.")
    if rows.empty:
        st.info("No issue entries for this filter.")
        return
    df = pd.DataFrame({"ID": rows["id"].values, "Date": rows["date"].values, "Factory": rows["factory_name"].values,
                       "Item": rows["item_name"].values, "Size": rows["size"].values, "Qty": rows["qty"].astype(float).values,
                       "Officer": rows["officer_name"].values,
                       "ERP status": rows["po_flag"].map({"Pending": "ERP PO Pending", "Done": "ERP Entry Done"}).fillna("").values,
                       "ERP PO Pending": (rows["po_flag"] == "Pending").values})
    gen = st.session_state.get("il_po_gen", 0)
    edited = st.data_editor(df, hide_index=True, use_container_width=True, height=380, key=f"il_po_ed_{gen}",
                            disabled=[c for c in df.columns if c != "ERP PO Pending"],
                            column_config={"ERP PO Pending": st.column_config.CheckboxColumn("ERP PO Pending ✔"),
                                           "Qty": st.column_config.NumberColumn(format="%.2f")})
    on = df.loc[edited["ERP PO Pending"].astype(bool) & ~df["ERP PO Pending"], "ID"].tolist()
    off = df.loc[~edited["ERP PO Pending"].astype(bool) & df["ERP PO Pending"], "ID"].tolist()
    n = len(on) + len(off)
    if st.button(f"💾 Save ERP PO tags ({len(on)} tag, {len(off)} untag)", key="il_po_save", type="primary",
                 disabled=(n == 0), use_container_width=True) and guard():
        if set_po_pending_flags(on, off):
            st.session_state["il_po_gen"] = gen + 1
            done(f"ERP PO Pending updated: {len(on)} tagged, {len(off)} untagged.")


